function validate([height, width, tree, squirrel, nuts]) {
  if (!Number.isInteger(height) || !Number.isInteger(width) || height < 1 || width < 1 || height > 100 || width > 100) return 'height and width are between 1 and 100.';
  if (!Array.isArray(nuts) || nuts.length < 1 || nuts.length > 5000) return 'nuts needs 1 to 5000 positions.';
  for (const cell of [tree, squirrel, ...nuts]) {
    if (!Array.isArray(cell) || cell.length !== 2) return 'Every position is a [row, col] pair.';
    if (cell[0] < 0 || cell[0] >= height || cell[1] < 0 || cell[1] >= width) return 'Every position lies inside the grid.';
  }
  return null;
}

