function minDistance(height, width, tree, squirrel, nuts) {
  let total = 0;
  let bestSaving = -Infinity;

  for (const [row, col] of nuts) {
    const toTree = Math.abs(row - tree[0]) + Math.abs(col - tree[1]);
    const fromSquirrel = Math.abs(row - squirrel[0]) + Math.abs(col - squirrel[1]);
    total += 2 * toTree;
    bestSaving = Math.max(bestSaving, toTree - fromSquirrel);
  }
  return total - bestSaving;
}

