function minDistance(height, width, tree, squirrel, nuts) {
  const steps = (a, b) => Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]);
  const used = new Array(nuts.length).fill(false);
  let best = Infinity;
  // Try every order of the nuts and walk it: start -> nut -> tree -> nut -> tree ...
  const walk = (at, done, moves) => {
    if (moves >= best) return;
    if (done === nuts.length) { best = moves; return; }
    for (let i = 0; i < nuts.length; i++) {
      if (used[i]) continue;
      used[i] = true;
      walk(tree, done + 1, moves + steps(at, nuts[i]) + steps(nuts[i], tree));
      used[i] = false;
    }
  };
  walk(squirrel, 0, 0);
  return best;
}

