function generate(rand, size) {
  const height = size === 'large' ? 100 : 1 + Math.floor(rand() * 6);
  const width = size === 'large' ? 100 : 1 + Math.floor(rand() * 6);
  const cell = () => [Math.floor(rand() * height), Math.floor(rand() * width)];
  const count = size === 'large' ? 2000 : 1 + Math.floor(rand() * 6);
  const nuts = Array.from({ length: count }, cell);
  return [height, width, cell(), cell(), nuts];
}
